entries[164732] = { ["name"] = "Ub3r-Construct: Short-Fused Boom Bots", ["text"] = "Binds when picked up\nUnique (5)\nUse: Summons an army of Short-Fused Boom Bots to assist the caster for 20 seconds. (3 Sec Cooldown)\nRequires Kul Tiran Engineering (50)" }
entries[164733] = { ["name"] = "Synchronous Thread", ["text"] = "Binds when picked up\nUnique\nKul Tiran and Zandalari cloth displaced in time can be found more often in the world.\nUse: Allows Synchronous Tailors to mend tears in the fabric of time across Kul Tiras and Zandalar.\nRequires Kul Tiran Tailoring (150)\n\"A stitch in time saves the world from its demise.\"" }
