entries[164740] = { ["name"] = "Ub3r-Spanner", ["text"] = "Binds when picked up\nUnique\nEnables the engineer to craft Ub3r-Constructs.\nUse: Summons an Ub3r-Construct to assist the caster for 20 seconds. If no Ub3r-Construct is specified, a random one will appear. (15 Min Cooldown)\nRequires Kul Tiran Engineering (150)" }
entries[164741] = { ["name"] = "Unstable Azerite Grenade", ["text"] = "Binds when picked up\nUnique (20)\nDuration: 5 min (real time)\nUse: Deals 10 to 16 Arcane damage to all enemies within 7 yards of impact. (5 Sec Cooldown)\nGrants the Azerite Grenade ability." }
