entries[164761] = { ["name"] = "Xal'atath, Blade of the Black Empire", ["text"] = "Quest Item\nUnique\n\"Xal'atath has a mind of its own. Once a prized weapon of priests used against the Burning Legion, this artifact has lost its power and is in a dormant state. For now.\"" }
entries[164762] = { ["name"] = "Kul Tiran Charger", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nRequires any Alliance race\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Kul Tiran Charger.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The Kul Tiran military prides itself on mastery of both sea, through a vast navy, and land, with armed cavalry.\"\nAchievement:\nAllied Races: Kul Tiran Human" }
entries[164763] = { ["name"] = "Trident of Deep Ocean", ["text"] = "Quest Item\n\"If you hold this up to your ear, you can hear the ocean.\"" }
entries[164764] = { ["name"] = "Trident Head", ["text"] = "Quest Item\nThe voice of the ocean will protect you.\n\"The ferocious prongs would work as a vicious melee weapon. Combine with the Trident Haft.\"" }
entries[164766] = { ["name"] = "Iwen's Enchanting Rod", ["text"] = "Binds when picked up\nUnique\nGain extra resources when disenchanting.\nUse: Consume 1 Veiled Crystal to animate an inert golem. (5 Sec Cooldown)\nRequires Kul Tiran Enchanting (150)\n\"Drust magic causes the rod to thrum with power. Can also serve as any lesser runed enchanting rod.\"" }
