entries[164773] = { ["name"] = "Gryzix's Decoder", ["text"] = "Quest Item\n\"Capable of deciphering encrypted documents from Ashenvale to Zangarmarsh. This can be used to decode the Ub3r-Spanner Recipe.\"" }
